property.code:
require.config({
  paths: {
    'xwiki-propertize': "$services.webjars.url('com.xwiki.commons:xwiki-pro-commons-webjar', 'xwikiPropertize/xwikiPropertize.js')"
  }
});
require(['jquery', 'xwiki-propertize', 'xwiki-selectize'], function ($) {
  console.log('hello there');
  let linkInputs = function (config) {
    if (!config || !config.primaryInput) {
      return;
    }
    let linkedInputs = config.linkedInputs || [];
    config.unsynched = false;
    linkedInputs.forEach(linkedInput => {
      let linkedElem = $(linkedInput.selector);
      linkedElem.on('change', function () {
        config.unsynched = true;
      });
      linkedInput.element = linkedElem;
    });
    let primaryElem = $(config.primaryInput);
    primaryElem.on('input', function () {
      if (config.unsynched) {
        if (primaryElem.val() != '' || config.linkedInputs.filter(e => e.element.val() != '').size() > 0) {
          return;
        } else {
          config.unsynched = false;
        }
      }
      let currentVal = primaryElem.val();
      for (let i in config.ignoredSuffixes) {
        if (currentVal.toLowerCase().endsWith(config.ignoredSuffixes[i])) {
          currentVal = currentVal.substr(0, currentVal.length - config.ignoredSuffixes[i].length);
          break;
        }
      }
      for (let i in config.ignoredPrefixes) {
        if (currentVal.toLowerCase().startsWith(config.ignoredPrefixes[i])) {
          currentVal = currentVal.substr(config.ignoredPrefixes[i].length, currentVal.length);
          break;
        }
      }
      currentVal = currentVal.endsWith(config.ignoredSuffix) ? currentVal.substr(0, currentVal.length - (config.ignoredSuffix || '').length) : currentVal;
      currentVal = currentVal.startsWith(config.ignoredPrefix) ? currentVal.substr((config.ingoredPrefix || '').length, currentVal.length) : currentVal;
      config.linkedInputs.forEach(linkedInput => linkedInput.element.val((linkedInput.prefix || '') + currentVal + (linkedInput.suffix || '')));
    });
  };
  linkInputs({
    primaryInput: '#XWiki\\.OIDC\\.ClientConfigurationClass_0_authorizationEndpoint',
    ignoredSuffixes: ['/auth', '/authorize', '/authorization'],
    ignoredPrefixes: [],
    linkedInputs: [
      {
        selector: '#XWiki\\.OIDC\\.ClientConfigurationClass_0_tokenEndpoint',
        suffix: '/token',
        prefix: ''
      },
      {
        selector: '#XWiki\\.OIDC\\.ClientConfigurationClass_0_userInfoEndpoint',
        suffix: '/userinfo',
        prefix: ''
      }
    ]
  });
  $('#XWiki\\.OIDC\\.ClientConfigurationClass_0_userMapping').xwikiPropertize({
    separator: '|'
  });
  $('#XWiki\\.OIDC\\.ClientConfigurationClass_0_groupsMapping').xwikiPropertize({
    separator: '|'
  });
  $('.oidcpro-property').each(function () {
    let selectizeCfg = $(this).data('selectize');
    if (selectizeCfg) {
      $(this).find('input').xwikiSelectize(selectizeCfg);
    }
  });
  // XWiki.OIDC.ClientConfigurationClass_0_groupsMapping
});

.oidcpro-section-header-icon {
  transition: all 0.5s;
  display: inline-block;
}

a.collapsed .oidcpro-section-header-icon {
  transform: rotate(-180deg);
  -moz-transform: rotate(-180deg);
  -webkit-transform: rotate(-180deg);
}

.oidcpro-section-header {
  display: flex;
  gap: 1em;
  align-items: baseline;
}

.oidcpro-collapse-link {
  margin: 0 0 0 1em;
}
.oidcpro-collapse-link:has(h2) {
  color: inherit !important;
  text-decoration: none !important;
}

.oidcpro-property {
  margin: 0 0 1em 0;
}

.oidcpro-properties {
  padding-top: 1em;
}
